        Ok(Some(Token::Ident(ident)))
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let mut num = String::new();

        // Handle leading minus separately (it's a token on its own)
        if self.next_is('-') {
            return None;
        }

        // Integer part
        while let Some(c) = self.chars.next_if(|&ch| ch.is_ascii_digit()) {
            num.push(c);
        }

        // Decimal point and fractional part
        if self.next_is('.') {
            num.push('.');
            while let Some(c) = self.chars.next_if(|&ch| ch.is_ascii_digit()) {
                num.push(c);
            }
        }

        // Exponent
        if self.next_is('e') || self.next_is('E') {
            num.push('e');
            if self.next_is('+') || self.next_is('-') {
                num.push(self.chars.next().unwrap());
            }
            while let Some(c) = self.chars.next_if(|&ch| ch.is_ascii_digit()) {
                num.push(c);
            }
        }

        if !num.is_empty() {
            Some(Token::Number(num))
        } else {
            None
        }
    }

    /// Scans the next quoted string literal, if any.
    fn scan_string(&mut self) -> Result<Option<Token>> {
        if !self.next_is('\'') {
            return Ok(None);
        }

        let mut s = String::new();
        loop {
            match self.chars.next() {
                Some('\'') => {
                    // Check for escaped quote
                    if self.next_is('\'') {
                        s.push('\'');
                    } else {
                        break;
                    }
                }
                Some('\\') => {
                    if let Some(c) = self.chars.next() {
                        s.push(c);
                    }
                }
                Some(c) => s.push(c),
                None => return Err(errinput!("unterminated string literal")),
            }
        }

        Ok(Some(Token::String(s)))
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Option<Token> {
        let c = self.chars.next()?;
        match c {
            '.' => Some(Token::Period),
            '=' => Some(Token::Equal),
            '!' => {
                if self.next_is('=') {
                    Some(Token::NotEqual)
                } else {
                    Some(Token::Exclamation)
                }
            }
            '>' => {
                if self.next_is('=') {
                    Some(Token::GreaterThanOrEqual)
                } else {
                    Some(Token::GreaterThan)
                }
            }
            '<' => {
                if self.next_is('=') {
                    Some(Token::LessThanOrEqual)
                } else if self.next_is('>') {
                    Some(Token::LessOrGreaterThan)
                } else {
                    Some(Token::LessThan)
                }
            }
            '+' => Some(Token::Plus),
            '-' => Some(Token::Minus),
            '*' => Some(Token::Asterisk),
            '/' => Some(Token::Slash),
            '^' => Some(Token::Caret),
            '%' => Some(Token::Percent),
            '?' => Some(Token::Question),
            ',' => Some(Token::Comma),
            ';' => Some(Token::Semicolon),
            '(' => Some(Token::OpenParen),
            ')' => Some(Token::CloseParen),
            _ => None,
        }
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while self.chars.peek().map_or(false, |&c| c.is_whitespace()) {
            self.chars.next();
        }
    }
}

/// Returns true if the entire given string is a single valid identifier.
pub fn is_ident(ident: &str) -> bool {
    let mut chars = ident.chars();
    let first = chars.next();
    match first {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_alphanumeric() || c == '_')
}

